def backfill_workshop_settlements(apps, schema_editor):
    AccountingPeriod = apps.get_model("settlement", "AccountingPeriod")
    WorkshopSettlement = apps.get_model("settlement", "WorkshopSettlement")
    for period in AccountingPeriod.objects.all():
        workshops = set(
            period.production_orders.exclude(workshop="").values_list(
                "workshop", flat=True
            )
        )
        workshops.update(
            period.workshop_cost_pools.exclude(workshop="").values_list(
                "workshop", flat=True
            )
        )
        completed = period.status in {"calculated", "reviewed", "locked"}
        for sequence, workshop in enumerate(sorted(workshops), 1):
            order_cost = sum(
                (
                    item.total_cost
                    for item in period.order_cost_results.filter(
                        order__workshop=workshop
                    )
                ),
                Decimal("0"),
            )
            receipt_amount = sum(
                (
                    item.amount or Decimal("0")
                    for item in period.match_allocations.filter(
                        kind="production_receipt",
                        production_order__workshop=workshop,
                    )
                ),
                Decimal("0"),
            )
            WorkshopSettlement.objects.create(
                period=period,
                workshop=workshop,
                sequence=sequence,
                status="settled" if completed else "pending",
                iterations=1 if completed else 0,
                converged=completed,
                settled_at=period.last_run_at if completed else None,
                settled_by_id=period.locked_by_id if completed else None,
                order_cost=order_cost,
                production_receipt_amount=receipt_amount,
            )


